document.addEventListener("DOMContentLoaded",function(event){function dragElement(sElementId){function closeDragElement(){document.onmouseup=null;document.onmousemove=null;}
function elementDrag(oEvent){oEvent=oEvent||window.event;oEvent.preventDefault();iPos1=iPos3-oEvent.clientX;iPos2=iPos4-oEvent.clientY;iPos3=oEvent.clientX;iPos4=oEvent.clientY;oElement.style.top=(oElement.offsetTop-iPos2)+"px";oElement.style.left=(oElement.offsetLeft-iPos1)+"px";localStorage.setItem(sElementId,'{"top":'+(oElement.offsetTop-iPos2)+',"left":'+(oElement.offsetLeft-iPos1)+'}');}
function dragMouseDown(oEvent){oEvent=oEvent||window.event;oEvent.preventDefault();iPos3=oEvent.clientX;iPos4=oEvent.clientY;document.onmouseup=closeDragElement;document.onmousemove=elementDrag;}
function restore(oElement){var sPosition=localStorage.getItem(oElement.id);(null===sPosition)?sPosition='{"top":'+((window.innerHeight/4))+',"left":'+((window.innerWidth/4))+'}':false;var oPosition=JSON.parse(sPosition);oElement.style.top=oPosition.top+'px';oElement.style.left=oPosition.left+'px';oElement.style.display='block';}
var oElement=document.getElementById(sElementId);var iPos1=0,iPos2=0,iPos3=0,iPos4=0;restore(oElement);oElement.onmousedown=dragMouseDown;}
for(var oElement of document.getElementsByClassName('draggable')){dragElement(oElement.id);}});